; stick.asm -- chapter 16: the cursor keys, two ways
; generated by gen16.py
        INCLUDE "msx.inc"
        OUTPUT "stick.rom"
        ORG $4000
        CART_HEADER init
VARS    EQU RAM_START + $100    ; the program's variables: the code is in ROM
        INCLUDE "bios.inc"
RESULTS EQU RAM_START          ; what the program found: the debugger reads it here
; The cursor keys read twice, by GTSTCK and by stick, which asks the keyboard
; itself; the debugger holds keys down from INIT on and compares.
init:   di
        ld sp, SYS_AREA
s1:     xor a
        call GTSTCK             ; the BIOS's way
s2:     ld (RESULTS), a
s3:     call stick              ; straight from the keyboard
s4:     ld (RESULTS+1), a
stop:   jr stop

; stick: A = the direction of the cursor keys, 0 to 8, as GTSTCK gives it:
;        row 8 of the keyboard, read through the PPI (chapter 3), and its four
;        top bits, which are 0 for a key held down, looked up in a table.
;        Uses A, H, L.
stick:  in a, (PPI_C)
        and $F0                 ; keep the PPI's other outputs
        or 8                    ; row 8: the cursor keys in bits 4 to 7
        out (PPI_C), a
        in a, (PPI_B)
        rrca
        rrca
        rrca
        rrca
        and $0F                 ; right, down, up, left: 0 when held
        ld l, a
        ld h, high sticks
        ld a, (hl)
        ret

        ALIGN 256               ; stick puts the four bits in L
sticks: db 0, 3, 5, 4, 1, 2, 0, 3, 7, 0, 6, 5, 8, 1, 7, 0
        ASSERT $ <= $8000, the program is longer than the cartridge
        ds $8000 - $, $FF       ; pad the cartridge to 16 KB
